355:
SELECT DISTINCT "keywords"
FROM "cards"
WHERE "name" LIKE '%Angel of Mercy%';

509:
SELECT "id"
FROM "sets"
WHERE "baseSetSize" = (
    SELECT MAX(CAST("baseSetSize" AS INTEGER))
    FROM "sets"
);

588:
SELECT COUNT(*) AS total_comments
FROM "comments"
WHERE CAST("userid" AS BIGINT) = 13;

745:
SELECT DISTINCT "publisher"."id"
FROM "publisher"
WHERE "publisher"."publisher_name" LIKE '%Star Trek%';

747:
SELECT COUNT(*) AS total_number
FROM "superhero"
WHERE "full_name" IS NULL OR TRIM("full_name") = '-';

1377:
SELECT COUNT(DISTINCT "member_id") AS count
FROM "member"
WHERE LOWER("position") LIKE '%president%';
